/**
 * src/src/config/repoPrompts.json IS CURRENT.
 *
 * The admin Prompts library says "Repo has a newer version" by comparing each
 * live prompt with this file (docs/design/prompt-versions/). It is generated by
 * scripts/build-repo-prompts.js from demo-sets/*.prompt.json and
 * lambda-functions/admin/default-ai-prompts.json, run in src/'s `prebuild`, and
 * COMMITTED. A prompt file edited without re-running the script would ship a
 * library that compares against yesterday's text — so this fails until it is.
 *
 * Also pinned: the hashes in the file are the lambda's own (prompt-versions.js),
 * so the live side and the repo side agree on "the same"; and `prebuild` runs
 * the script.
 */
const assert = require('assert');
const path = require('path');
const fs = require('fs');

const REPO = path.join(__dirname, '..');
const builder = require(path.join(REPO, 'scripts', 'build-repo-prompts.js'));
const versions = require(path.join(REPO, 'lambda-functions', 'admin', 'shared', 'prompt-versions.js'));

let failed = 0;
function check(name, fn) {
  try { fn(); console.log(`  ✓ ${name}`); } catch (e) { failed++; console.log(`  ✗ ${name}\n    ${e.message}`); }
}

const committed = JSON.parse(fs.readFileSync(builder.OUT, 'utf8'));

console.log('repoPrompts.json');
check('is current with its sources (run node scripts/build-repo-prompts.js if not)', () => {
  assert.ok(builder.isFresh(committed), 'src/src/config/repoPrompts.json is stale');
});

check('carries every demo-sets/*.prompt.json and every built-in default', () => {
  const demo = fs.readdirSync(path.join(REPO, 'demo-sets')).filter((f) => f.endsWith('.prompt.json'));
  const defaults = require(path.join(REPO, versions.DEFAULTS_REPO_PATH));
  const nDefaults = Object.values(defaults).reduce((n, c) => n + Object.keys(c).length, 0);
  assert.strictEqual(committed.prompts.length, demo.length + nDefaults);
  for (const f of demo) assert.ok(committed.prompts.some((p) => p.key === `demo-sets/${f}`), f);
});

check('every entry has a name, a game type, its fields and the lambda\'s hashes of them', () => {
  for (const p of committed.prompts) {
    assert.ok(p.name && p.gameType && p.path && p.key, p.key);
    assert.ok(p.fields.includes('instructions') || p.fields.includes('template'), `${p.key}: no text`);
    assert.deepStrictEqual(p.fieldHashes, versions.fieldHashes(p.values, p.fields), `${p.key}: field hashes`);
    assert.strictEqual(p.hash, versions.contentHash(p.values, p.fields), `${p.key}: hash`);
  }
});

check('a stale file is caught (one changed word)', () => {
  const tampered = JSON.parse(JSON.stringify(committed));
  tampered.prompts[0].values.instructions += ' changed';
  tampered.prompts[0].hash = versions.contentHash(tampered.prompts[0].values, tampered.prompts[0].fields);
  assert.strictEqual(builder.isFresh(tampered), false);
});

check('a changed commit date alone is not staleness', () => {
  const moved = JSON.parse(JSON.stringify(committed));
  moved.prompts[0].commitDate = '2001-01-01';
  assert.strictEqual(builder.isFresh(moved), true);
});

check('src/package.json runs the script before every build', () => {
  const pkg = JSON.parse(fs.readFileSync(path.join(REPO, 'src', 'package.json'), 'utf8'));
  assert.match(pkg.scripts.prebuild || '', /build-repo-prompts\.js/);
});

if (failed) {
  console.log(`\n${failed} failed`);
  process.exit(1);
}
console.log('\nall passed');
